Definition pcore_init_a : pcore := mkPC 1 1048576 0 0 0 8192 0 FL_EAGER.

(* [comment removed for export] *)
Definition hz_sh3 : list cell :=
  [CB 4 (poison_bytes 4 0xf1); CB 2 (poison_bytes 2 0xf8); CB 2 (poison_bytes 2 0xf2); CB 3 (poison_bytes 3 0);
   CB 5 (poison_bytes 5 0xf2); CB 3 (poison_bytes 3 0); CB 5 (poison_bytes 5 0xf2); CB 44 (poison_bytes 44 0);
   CB 8 (poison_bytes 8 0xf3); CB 52 (poison_bytes 52 0)].

Lemma hz_sh3_pr : forall m A, rw_cells asegs m A hz_sh3 -> rw_cells asegs m (A + 24) [CB 44 (poison_bytes 44 0)].
Proof.
  intros m A SH. unfold hz_sh3 in SH.
  apply (proj1 (rw_cells_app asegs m A [_; _; _; _; _; _; _] _)) in SH. destruct SH as [_ SH]. cbn [cells_size csize Nat.add] in SH.
  apply (proj1 (rw_cells_app asegs m _ [_] _)) in SH. destruct SH as [SH _].
  replace (A + Z.of_nat 24) with (A + 24) in SH by lia. exact SH.
Qed.

(* [comment removed for export] *)
Definition hz_D1_W (lo spa ff : Z) : list (Z * Z) :=
  [(lo, spa); (ff + 192, ff + 544); (Z.shiftr ff 3 + 2147450880 + 24, Z.shiftr ff 3 + 2147450880 + 68)]%Z.

Section HCW.
  Context {HCEIL : HeapCeil}.
  Variable H : asr.
  Hypothesis HH : asan_rt_hyps H.

Definition hz_D1_post (sp gp tp s11 : word) (F : bvmap 5 word) (fc : bv 32) (LF : list fframe)
    (spa ff fp lo shi : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a4 a5 a6 a7 t3 t4 t5 t6 m' (pad7 pad2 j13 j32a j8a j32b j8b : list byte),
    ms' = MS (mkR (Z_to_bv 64 P_HZ_RET_SRO) (Z_to_bv 64 spa) gp tp t0 t1 t2 sp (Z_to_bv 64 spa)
                  (Z_to_bv 64 (spa + 16)) (Z_to_bv 64 (spa + 48)) (Z_to_bv 64 (ff + 192)) (Z_to_bv 64 (ff + 64)) a4 a5 a6 a7
                  (Z_to_bv 64 ff) (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) (Z_to_bv 64 (ff + 128)) (Z_to_bv 64 (ff + 64))
                  (Z_to_bv 64 (ff + 192)) (Z_to_bv 64 (ff + 272)) (Z_to_bv 64 (ff + 280)) (Z_to_bv 64 ff) (Z_to_bv 64 2147450880) s11 t3 t4 t5 t6)
             F (Z_to_bv 64 P_A_SYNC_READ_OP) fc None m' (seg_rom asegs)
    /\ munch (hz_D1_W lo spa ff) m m' /\ wmono asegs m m' /\ mem_inv asegs m' /\ stk asegs m' lo spa
    /\ rw_cells asegs m' (ff + 192) (ParserCoreCells pcore_init_a pad7 pad2)
    /\ rw_cells asegs m' (ff + 272) (NodeCells (init_header_node (ff + 272)) (zeros 4))
    /\ rw_cells asegs m' (ff + 304) (LNodeCells (init_lheader_node (ff + 304)))
    /\ rw_cells asegs m' (ff + 320) (HdrCells (mkHV 0 0 0 0 11 0))
    /\ rw_cells asegs m' (ff + 360) (MBufHdrCells (ff + 368) (ff + 368) (ff + 368) 0 0 0 0)
    /\ rw_cells asegs m' (ff + 424) [C8 (wz (ff + 360))]
    /\ rw_cells asegs m' (ff + 432) [C1 (b8 0); C1 (b8 0); C1 (b8 0); CB 13 j13]
    /\ rw_cells asegs m' (ff + 448) [CB 32 j32a; C8 (wz 0); CB 8 j8a]
    /\ rw_cells asegs m' (ff + 496) [CB 32 j32b; C8 (wz 0); CB 8 j8b]
    /\ rw_cells asegs m' (Z.shiftr ff 3 + 2147450880) hz_sh3
    /\ as_RFS H ((4, ff, fp) :: LF) m' /\ ACONST m' /\ stack0 m' lo shi.

(* [comment removed for export] *)
Tactic Notation "hz_acc" hyp(SH3) hyp(MUb) hyp(WMb) ident(ACCx) "by" tactic3(tac) :=
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mc _) =>
    let SHx := fresh "SHx" in
    pose proof SH3 as SHx; unkeep SHx; unfold hz_sh3 in SHx;
    tr_keep SHx over MUb WMb by tac;
    lazymatch goal with F3x : ?ff mod 8 = 0, APFx : aapp ?ff 1024 |- _ =>
      pose proof (prep_frame_acc mc ff 192 44 _ ltac:(pose proof (aapp_bounds _ _ APFx ltac:(clear; lia)) as (_ & _ & _ & K & _); clear - K; lia) F3x
                    ltac:(clear; lia) ltac:(clear; reflexivity) ltac:(clear; lia)
                    ltac:(pose proof (aapp_bounds _ _ APFx ltac:(clear; lia)) as (_ & _ & K & _); clear - K; lia)
                    ltac:(replace (Z.shiftr ff 3 + 2147450880 + 192 / 8) with (Z.shiftr ff 3 + 2147450880 + 24) by (clear; reflexivity); exact (hz_sh3_pr _ _ SHx))
                    eq_refl) as ACCx;
      change (8 * 44) with 352 in ACCx; clear SHx
    end end.

(* [comment removed for export] *)
Tactic Notation "hz_memset" hyp(M1) constr(dst) constr(n) hyp(SH3) hyp(MUb) hyp(WMb) hyp(PSV1) hyp(WHb) hyp(MU) hyp(FWIN) hyp(RF) hyp(AC) hyp(SK) hyp(FF) "by" tactic3(tac) :=
  lazymatch goal with STx : stk _ ?mc ?lo ?spa, MIx : mem_inv _ ?mc |- evt _ _ (MS _ _ _ _ _ ?mc _) =>
  lazymatch type of M1 with rw_cells _ _ _ [CB _ ?j] =>
  lazymatch goal with F1x : 6811648 + 36864 <= ?ff, F2x : ?ff + 1024 <= aceil, APFx : aapp ?ff 1024, CEILx : aceil <= ?lo, Hhh : asan_rt_hyps ?Hh |- _ =>
    let ACCx := fresh "ACCx" in let SVx := fresh "SVx" in let RFx := fresh "RFx" in let ACx := fresh "ACx" in let SKx := fresh "SKx" in
    hz_acc SH3 MUb WMb ACCx by tac;
    assert (SVx : shvis mc (ff + 192) (ff + 192 + 352))
      by (eapply shvis_transport_hi; [exact PSV1| exact MUb| exact WMb| clear - F1x; lia| unfold AAPP_HI; clear - F2x; pose proof aceil_facts; lia| exact WHb]);
    destruct (fs_frame_writes _ Hhh _ _ _ _ _ _ _ _ _ RF AC SK FF MU ltac:(assumption) FWIN) as (RFx & ACx & SKx);
    lazymatch goal with |- evt _ _ (MS _ ?F _ ?fc _ _ _) =>
    callZc (asan_memset_specZ (ah_memset Hh Hhh) _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ F fc mc spa dst 0 n j lo) (clear M1 RFx SKx);
    [ clear; lia | exact M1 | clear; lia | clear - F1x; lia
    | eapply accessible_sub; [exact ACCx| clear; lia| clear; lia| clear; lia]
    | eapply shvis_sub; [exact SVx| clear - F1x; lia| clear; lia| clear; lia| clear; lia| clear - F1x; lia]
    | eapply aapp_in_app_mem; [exact APFx| clear; lia| clear; lia]
    | eapply aconst_ok_aapp; [exact APFx| cbn [fst snd]; clear; lia| cbn [fst snd]; clear; lia]
    | exact STx | exact CEILx | tac | tac | left; clear - F2x CEILx; lia | exact MIx | exact ACx | clear ACCx SVx ACx ] end end end end.

